import 'package:brick_offline_first/brick_offline_first.dart';

class PersonRepository extends OfflineFirstRepository with DeleteAllMixin {
  PersonRepository({required super.localProvider, required super.remoteProvider});

  Future<Person?> getPerson(int id) => get<Person>(id);
}

// Usage
final repo = PersonRepository(
  localProvider: SqliteProvider(...),
  remoteProvider: RestProvider(...),
);
final person = await repo.getPerson(1);
